final class Round3Verification {
 static final BlockPos O=new BlockPos(0,81,0);static final List<String> checks=new ArrayList<>();
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks.add(why);}
 static ItemStack wand(){var w=new ItemStack(R3Equipment.WAND.get());w.set(WandComponents.PARTS.get(),new WandParts("silverwood","thaumium"));for(var a:Aspects.PRIMALS)WandVis.set(w,a,WandVis.capacity(w));return w;}
 static ThaumicGolem golem(ServerLevel l,BlockPos source,int core,GolemMaterial material,boolean advanced){var body=new ItemStack(R3Equipment.GOLEM_BODIES.get(material).get());CustomData.update(DataComponents.CUSTOM_DATA,body,t->{t.putInt("core",core);t.putBoolean("advanced",advanced);});var g=R3Entities.GOLEM.get().create(l);g.initialize(material,UUID.randomUUID(),source.above(),Direction.UP,body);g.moveTo(source.above().getCenter());l.addFreshEntity(g);return g;}
 static TransportBlockEntity transport(ServerLevel l,BlockPos p,Block b){l.setBlockAndUpdate(p,b.defaultBlockState());return (TransportBlockEntity)l.getBlockEntity(p);}
 static int amount(ItemStack s){return s.getOrDefault(DataComponents.BLOCK_ENTITY_DATA,CustomData.EMPTY).copyTag().getCompound("Essentia").getInt("ignis");}
 static void register(MinecraftServer server){try{
  var l=server.overworld();for(int x=-1;x<=3;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);
  for(var p:BlockPos.betweenClosed(O.offset(-10,-1,-10),O.offset(45,9,10)))l.setBlock(p,p.getY()==80?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  var player=new FakePlayer(l,new GameProfile(UUID.randomUUID(),"Round3Audit"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.moveTo(O.getCenter());KnowledgeService.initialize(player);
  var ale=transport(l,O,R3Content.ALEMBIC.get());ale.store.setAspects(new AspectList().add(Aspects.FIRE,32));var jar=new ItemStack(R3Content.WARDED_JAR.get().asItem());player.setItemInHand(InteractionHand.MAIN_HAND,jar);
  check(ale.getBlockState().useItemOn(jar,l,player,InteractionHand.MAIN_HAND,new BlockHitResult(O.getCenter(),Direction.UP,O,false)).consumesAction(),"actual block interaction fills empty held jar");check(amount(player.getMainHandItem())==32&&ale.store.amount()==0,"jar captures all 32 essentia atomically");
  ale.store.setAspects(new AspectList().add(Aspects.FIRE,32));check(ale.useJar(player.getMainHandItem(),player,InteractionHand.MAIN_HAND)&&amount(player.getMainHandItem())==64,"matching jar tops up to 64");ale.store.setAspects(new AspectList().add(Aspects.FIRE,32));check(!ale.useJar(player.getMainHandItem(),player,InteractionHand.MAIN_HAND)&&ale.store.amount()==32,"full jar leaves source unchanged");
  player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Content.VOID_JAR.get().asItem()));for(int i=0;i<3;i++){ale.store.setAspects(new AspectList().add(Aspects.FIRE,32));check(ale.useJar(player.getMainHandItem(),player,InteractionHand.MAIN_HAND)&&ale.store.amount()==0,"void jar drains source including overflow "+i);}check(amount(player.getMainHandItem())==64,"void capacity remains 64");
  jar=new ItemStack(R3Content.WARDED_JAR.get().asItem());CustomData.update(DataComponents.BLOCK_ENTITY_DATA,jar,t->t.putString("AspectFilter","aqua"));player.setItemInHand(InteractionHand.MAIN_HAND,jar);ale.store.setAspects(new AspectList().add(Aspects.FIRE,32));check(!ale.useJar(jar,player,InteractionHand.MAIN_HAND)&&ale.store.amount()==32,"jar filter rejects a different aspect");
  jar=new ItemStack(R3Content.WARDED_JAR.get().asItem(),2);player.getInventory().clearContent();player.setItemInHand(InteractionHand.MAIN_HAND,jar);check(ale.useJar(jar,player,InteractionHand.MAIN_HAND)&&player.getMainHandItem().getCount()==1&&player.getInventory().items.stream().mapToInt(Round3Verification::amount).sum()==32,"stacked jars produce one filled jar without duplication");
  for(var m:GolemMaterial.values())for(boolean advanced:new boolean[]{false,true}){var g=golem(l,O.east(4),-1,m,advanced);check(g.upgradeSlots()==m.upgrades+(advanced?1:0),"original upgrade capacity "+m+" advanced="+advanced);for(int i=0;i<g.upgradeSlots();i++){player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_UPGRADES.get(i).get()));g.interact(player,InteractionHand.MAIN_HAND);}check(g.installedUpgrades()==g.upgradeSlots(),"all material slots accept upgrades "+m+advanced);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_UPGRADES.get(4).get()));g.interact(player,InteractionHand.MAIN_HAND);check(player.getMainHandItem().getCount()==1&&g.installedUpgrades()==g.upgradeSlots(),"full capacity rejects without consuming item "+m+advanced);g.discard();}
  for(int kind=0;kind<6;kind++){var g=golem(l,O.east(4),-1,GolemMaterial.THAUMIUM,true);for(int i=0;i<3;i++){player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_UPGRADES.get(kind).get()));g.interact(player,InteractionHand.MAIN_HAND);}check(g.upgrade(kind)==2&&player.getMainHandItem().getCount()==1,"max two identical upgrades, including Ordo, kind="+kind);g.discard();}
  var helmet=new ItemStack(R3Equipment.ARMOR.get("void_robe_helmet").get());check(thaumcraft.equipment.FortressArmor.goggles(helmet),"void robe hood grants revealing vision");check(helmet.is(net.minecraft.tags.ItemTags.DYEABLE),"void robe hood uses original dye tint");
  var relayPos=O.east(8);l.setBlockAndUpdate(relayPos,R3Content.VIS_RELAY.get().defaultBlockState());var relay=(VisRelayBlockEntity)l.getBlockEntity(relayPos);for(int i=0;i<6;i++){var shard=new ItemStack(R2Content.SHARDS.get(i).get());player.setItemInHand(InteractionHand.MAIN_HAND,shard);check(relay.getBlockState().useItemOn(shard,l,player,InteractionHand.MAIN_HAND,new BlockHitResult(relayPos.getCenter(),Direction.UP,relayPos,false)).consumesAction()&&relay.getAttunement()==i&&shard.getCount()==1,"actual shard attunement without consumption "+i);relay.getBlockState().useItemOn(shard,l,player,InteractionHand.MAIN_HAND,new BlockHitResult(relayPos.getCenter(),Direction.UP,relayPos,false));check(relay.getAttunement()==-1,"same shard clears attunement "+i);}
  relay.attune(2);relay.attune(6);check(relay.getAttunement()==-1,"balanced shard resets attunement");
  var create=new thaumcraft.network.NodeCreatePayload(O.east(12),0,0,Map.of("aer",42,"ignis",17));check(!create.apply(player),"node editor rejects non-operator");server.getPlayerList().op(player.getGameProfile());check(create.apply(player),"node editor accepts operator");check(((thaumcraft.blocks.AuraNodeBlockEntity)l.getBlockEntity(O.east(12))).state.current.equals(Map.of("aer",42,"ignis",17)),"node editor preserves selected quantities");check(!new thaumcraft.network.NodeCreatePayload(O.east(12),0,0,Map.of("unknown",1)).apply(player),"node editor rejects unknown aspect");
  var furnace=O.east(18).above();for(int part=0;part<27;part++)l.setBlockAndUpdate(furnace.offset(InfernalFurnaceBlock.offset(part)),part==22?Blocks.AIR.defaultBlockState():InfernalFurnaceBlock.original(part,Direction.SOUTH));check(InfernalFurnaceBlock.fits(l,furnace)==Direction.SOUTH,"documented furnace layout matches actual formation mask");var w=wand();player.setItemInHand(InteractionHand.MAIN_HAND,w);check(!InfernalFurnaceBlock.activate(player,w,furnace.below()),"infernal formation requires research");KnowledgeService.mutate(player,k->k.completeResearch("INFERNALFURNACE"));WandVis.set(w,Aspects.FIRE,0);check(!InfernalFurnaceBlock.activate(player,w,furnace.below()),"infernal formation requires fire vis");WandVis.set(w,Aspects.FIRE,10000);check(w.getItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(furnace.below().getCenter(),Direction.UP,furnace.below(),false))).consumesAction()&&l.getBlockState(furnace).is(R3Content.INFERNAL_FURNACE.get()),"actual wand use forms infernal furnace");check(thaumcraft.data.ResearchRecipePages.resolve("InfernalFurnace").equals("@infernal_furnace"),"book resolves infernal construction diagram");
  player.removeAllEffects();player.addEffect(new MobEffectInstance(WarpEffects.UNNATURAL_HUNGER,1800,2));NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.entity.living.LivingEntityUseItemEvent.Finish(player,new ItemStack(Items.ROTTEN_FLESH),32,ItemStack.EMPTY));check(player.getEffect(WarpEffects.UNNATURAL_HUNGER).getDuration()==1200&&player.getEffect(WarpEffects.UNNATURAL_HUNGER).getAmplifier()==1,"rotten flesh reduces hunger once, not twice");player.removeAllEffects();WarpService.dispatch(player,18,40);check(player.getEffect(WarpEffects.THAUMARHIA).getCures().isEmpty(),"warp-origin thaumarhia is not milk-curable");check(new MobEffectInstance(WarpEffects.THAUMARHIA,100).getCures().contains(EffectCures.MILK),"ordinary effect instance retains milk cure");check(!WarpEffects.DEATH_GAZE.get().shouldApplyEffectTickThisTick(100,0),"death gaze runs only through original player event handler");player.removeAllEffects();
  player.addEffect(new MobEffectInstance(WarpEffects.INFECTIOUS_EXHAUST,6000,2));check(Math.abs(WandVis.discount(player,Aspects.FIRE)+.3f)<.0001,"infectious exhaustion adds original 30 percent vis penalty at amplifier 2");player.addEffect(new MobEffectInstance(TaintEffects.VIS_EXHAUST,6000,1));check(Math.abs(WandVis.discount(player,Aspects.FIRE)+.3f)<.0001,"two exhaustion effects use highest severity, not stacked penalties");
  var infected=EntityType.COW.create(l);infected.moveTo(O.getCenter());l.addFreshEntity(infected);WarpEffects.INFECTIOUS_EXHAUST.get().applyEffectTick(player,2);check(infected.hasEffect(WarpEffects.INFECTIOUS_EXHAUST)&&infected.getEffect(WarpEffects.INFECTIOUS_EXHAUST).getAmplifier()==1&&infected.getEffect(WarpEffects.INFECTIOUS_EXHAUST).getDuration()==6000,"infection spreads within four blocks with original duration and lower tier");check(infected.getEffect(WarpEffects.INFECTIOUS_EXHAUST).getCures().contains(EffectCures.MILK),"secondary infection is milk-curable as in TC4");infected.discard();player.removeAllEffects();
  var cow=EntityType.COW.create(l);cow.moveTo(O.east(2).getCenter());l.addFreshEntity(cow);float health=cow.getHealth();TaintEffects.FLUX_TAINT.get().applyEffectTick(cow,0);check(cow.getHealth()==health-1,"flux taint deals one damage to ordinary living target");cow.discard();check(TaintEffects.FLUX_TAINT.get().shouldApplyEffectTickThisTick(40,0)&&!TaintEffects.FLUX_TAINT.get().shouldApplyEffectTickThisTick(39,0)&&TaintEffects.FLUX_TAINT.get().shouldApplyEffectTickThisTick(20,1),"flux taint uses original forty-tick interval divided by severity");
  player.addEffect(new MobEffectInstance(WarpEffects.DEATH_GAZE,6000));player.setYRot(180);player.setXRot(0);player.tickCount=10;var near=EntityType.COW.create(l);near.moveTo(.5,81,-4.5);l.addFreshEntity(near);var side=EntityType.COW.create(l);side.moveTo(4.5,81,-4.5);l.addFreshEntity(side);NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(player));check(near.hasEffect(MobEffects.WITHER)&&!side.hasEffect(MobEffects.WITHER),"death gaze uses original half-aperture .375 rad and sight check");near.discard();side.discard();player.removeAllEffects();
  var animated=golem(l,O.east(4),-1,GolemMaterial.WOOD,false);animated.action(10);var before=animated.action();animated.action(10);check(before==6&&animated.action()==6,"action timer retains original six ticks and does not restart while active");animated.discard();
  // Normal server scheduler: alchemy golem must approach the furnace below the selected cube.
  var base=O.east(30);l.setBlockAndUpdate(base,R3Content.ALCHEMY_FURNACE.get().defaultBlockState());var upper=transport(l,base.above(),R3Content.ALEMBIC.get());upper.store.setAspects(new AspectList().add(Aspects.FIRE,16));var destination=transport(l,base.east(4),R3Content.WARDED_JAR.get());var g=golem(l,base.above(),6,GolemMaterial.CLAY,false);g.moveTo(base.getX()-.5,81,base.getZ()+.5);g.mark(new GolemMarker(l.dimension(),destination.getBlockPos(),Direction.UP,-1),false);
  // A real powered bore executes findTarget against a solid wall with empty collision context.
  var bp=O.east(40);l.setBlockAndUpdate(bp,R3Content.BORE_BASE.get().defaultBlockState());l.setBlockAndUpdate(bp.above(),R3Content.BORE.get().defaultBlockState().setValue(ArcaneBoreBlock.FACING,Direction.NORTH));l.setBlockAndUpdate(bp.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());var bore=(ArcaneBoreBlockEntity)l.getBlockEntity(bp.above());bore.items.setItem(0,new ItemStack(R3Equipment.FOCI.get("excavation").get()));bore.items.setItem(1,new ItemStack(Items.DIAMOND_PICKAXE));for(int x=-3;x<=3;x++)for(int y=0;y<=4;y++)l.setBlockAndUpdate(bp.offset(x,y,-5),Blocks.STONE.defaultBlockState());
  int[] ticks={0};boolean[] sawTarget={false},sawProgress={false};NeoForge.EVENT_BUS.addListener((ServerTickEvent.Post e)->{if(e.getServer()!=server)return;int tick=++ticks[0];if(bore.target()!=null){sawTarget[0]=true;sawProgress[0]|=bore.miningProgress(0)>0;}if(tick<900)return;try{check(destination.store.amount()==16&&upper.store.amount()==0&&g.essentiaAmount==0,"ordinary alchemy scheduler collects elevated alembic and delivers all essentia");check(sawTarget[0]&&sawProgress[0],"powered bore acquires targets and advances mining progress without crash");finish(server,null);}catch(Throwable t){finish(server,t);}});
 }catch(Throwable t){finish(server,t);}}
 static void finish(MinecraftServer server,Throwable failure){try{var p=Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/golems-aura-tools-audit/round3/server-result.json");Files.createDirectories(p.getParent());var data=new LinkedHashMap<String,Object>();data.put("passed",failure==null);data.put("checks",checks);data.put("count",checks.size());if(failure!=null){data.put("error",failure.toString());thaumcraft.Thaumcraft.LOGGER.error("Round3 verification failed",failure);}Files.writeString(p,new GsonBuilder().setPrettyPrinting().create().toJson(data));}catch(Exception e){throw new RuntimeException(e);}server.halt(false);}
}
